import ast

import pytest

import sqlparse


@pytest.mark.parametrize(('query', 'expected'), [
    (r'SELECT \n, \t, \r', r"sql = 'SELECT \\n, \\t, \\r'"),
    (r'SELECT \\', r"sql = 'SELECT \\\\'"),
    ('SELECT \\', r"sql = 'SELECT \\'"),
    (r"SELECT 'a\'b'", r"sql = 'SELECT \'a\\\'b\''"),
    ('SELECT 1', "sql = 'SELECT 1'"),
])
def test_python_backslashes(query, expected):
    output = sqlparse.format(query, output_format='python')
    assert output == expected
    assert ast.literal_eval(ast.parse(output).body[0].value) == query


@pytest.mark.parametrize(('query', 'expected'), [
    (r'SELECT \n, \t, \r', r'$sql = "SELECT \\n, \\t, \\r";'),
    (r'SELECT \\', r'$sql = "SELECT \\\\";'),
    ('SELECT \\', r'$sql = "SELECT \\";'),
    (r'SELECT "a\"b"', r'$sql = "SELECT \"a\\\"b\"";'),
    ('SELECT 1', '$sql = "SELECT 1";'),
])
def test_php_backslashes(query, expected):
    assert sqlparse.format(query, output_format='php') == expected


@pytest.mark.parametrize(('output_format', 'expected'), [
    ('python', "sql = ('SELECT \\\\n '" + '\n' + "       'FROM t\\\\path')"),
    ('php', '$sql  = "SELECT \\\\n ";' + '\n' + '$sql .= "FROM t\\\\path";'),
])
def test_multiline_backslashes(output_format, expected):
    query = 'SELECT \\n\nFROM t\\path'
    assert sqlparse.format(query, output_format=output_format) == expected

import unittest
from itertools import count

import more_itertools as mi


class IchunkedBoundaryTests(unittest.TestCase):
    def test_zero_returns_no_chunks(self):
        for values in ([], [1], [1, 2, 3], count()):
            with self.subTest(values=type(values).__name__):
                self.assertEqual(list(mi.ichunked(values, 0)), [])

    def test_zero_preserves_input(self):
        source = iter([10, 20])
        list(mi.ichunked(source, 0))
        self.assertEqual(list(source), [10, 20])

    def test_negative_raises_even_for_empty_input(self):
        for n in (-1, -2, -100):
            for values in ([], [1, 2], count()):
                with self.subTest(n=n, values=type(values).__name__):
                    with self.assertRaisesRegex(ValueError, '^n must be at least 0$'):
                        list(mi.ichunked(values, n))

    def test_negative_preserves_input(self):
        source = iter([10, 20])
        try:
            list(mi.ichunked(source, -1))
        except ValueError:
            pass
        self.assertEqual(list(source), [10, 20])

    def test_positive_boundary_and_partial_chunk(self):
        for n, expected in ((1, [[1], [2], [3]]), (2, [[1, 2], [3]])):
            with self.subTest(n=n):
                self.assertEqual(
                    [list(chunk) for chunk in mi.ichunked([1, 2, 3], n)],
                    expected,
                )


if __name__ == '__main__':
    unittest.main()

import unittest

import more_itertools as mi


class FalsyError(Exception):
    def __bool__(self):
        return False


class BrokenRepr:
    def __repr__(self):
        raise RuntimeError('repr must not be called')


class CustomExceptionTests(unittest.TestCase):
    def test_falsy_too_long(self):
        for function in (mi.one, mi.only):
            with self.subTest(function=function.__name__):
                exc = FalsyError('requested')
                with self.assertRaises(FalsyError) as caught:
                    function(iter([1, 2]), too_long=exc)
                self.assertIs(caught.exception, exc)

    def test_falsy_too_short(self):
        exc = FalsyError('requested')
        with self.assertRaises(FalsyError) as caught:
            mi.one(iter([]), too_short=exc)
        self.assertIs(caught.exception, exc)

    def test_custom_exception_skips_broken_repr(self):
        for function in (mi.one, mi.only):
            for error_type in (FalsyError, RuntimeError):
                for items in ([BrokenRepr(), 2], [1, BrokenRepr()]):
                    with self.subTest(function=function.__name__,
                                      error_type=error_type, position=type(items[0]).__name__):
                        exc = error_type('requested')
                        with self.assertRaises(error_type) as caught:
                            function(iter(items), too_long=exc)
                        self.assertIs(caught.exception, exc)

    def test_exception_class_skips_broken_repr(self):
        for function in (mi.one, mi.only):
            with self.subTest(function=function.__name__):
                with self.assertRaises(IndexError):
                    function([BrokenRepr(), BrokenRepr()], too_long=IndexError)

    def test_none_uses_default_errors(self):
        for function in (mi.one, mi.only):
            with self.subTest(function=function.__name__):
                with self.assertRaises(ValueError) as caught:
                    function([1, 2], too_long=None)
                self.assertEqual(str(caught.exception),
                                 'Expected exactly one item in iterable, but got '
                                 '1, 2, and perhaps more.')
        with self.assertRaises(ValueError) as caught:
            mi.one([], too_short=None)
        self.assertEqual(str(caught.exception),
                         'too few items in iterable (expected 1)')

    def test_valid_cardinalities_ignore_custom_errors(self):
        item = BrokenRepr()
        exc = FalsyError('requested')
        self.assertIs(mi.one([item], too_short=exc, too_long=exc), item)
        self.assertIs(mi.only([item], too_long=exc), item)
        self.assertIs(mi.only([], default=item, too_long=exc), item)


if __name__ == '__main__':
    unittest.main()
